import { formulaTraces, planningRows, planningWorkbook, type PlanningRow } from '../../mock/business'
import { useWorkbenchStore } from '../../stores/workbench'

const workbench = useWorkbenchStore()
const route = useRoute()
const selectedOilfield = ref(planningRows.find((row) => row.warning)?.oilfield ?? planningRows[0]?.oilfield ?? '')
const schedulePanel = ref<HTMLElement | null>(null)

type ScheduleRow = {
  id: string
  oilfield: string
  plan: string
  workload: string
  impact: string
}

const scheduleRows: ScheduleRow[] = planningRows.map((row) => ({
  id: row.id,
  oilfield: row.oilfield,
  plan: row.state === '开发评价' ? '2027 Q2 投产' : '滚动实施',
  workload: row.state === '开发评价' ? '开发井 +2' : '调整井/措施复核',
  impact: row.warning || '联动产量剖面和版本差异。',
}))

function selectDetailRow(record: PlanningRow) {
  selectedOilfield.value = record.oilfield
  void nextTick(() => {
    schedulePanel.value?.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
  })
}

function detailRowClass(record: PlanningRow) {
  return record.oilfield === selectedOilfield.value ? 'row-selected' : ''
}

function scheduleRowClass(record: ScheduleRow) {
  return record.oilfield === selectedOilfield.value ? 'row-selected' : ''
}

